/**
 * Href builder for the Active Agents list. Sub-agents (rows where
 * `parentConversationId` is set) link to their parent chat with a
 * `?agent=<subConversationId>` query param; the chat page picks that up
 * and opens the right-side AgentDetailPanel for the sub-agent. Top-level
 * agents link directly to their own conversation.
 *
 * Rows without a `projectId` fall back to the `global` project segment.
 */
export interface ActiveAgentHrefInput {
	conversationId: string;
	parentConversationId: string | null;
	projectId: string | null;
}

export function buildActiveAgentHref(row: ActiveAgentHrefInput): string {
	const targetConvId = row.parentConversationId ?? row.conversationId;
	const projectSegment = row.projectId ?? "global";
	const query = row.parentConversationId
		? `?agent=${encodeURIComponent(row.conversationId)}`
		: "";
	return `/project/${projectSegment}/chat/${targetConvId}${query}`;
}
/**
 * Grouping logic for the Active Agents home page (`/active-agents`). Takes a
 * flat list of active-agent rows and groups them under their project so the
 * UI can show a project header above each bucket.
 *
 * Ordering rules:
 *   - Projects are sorted alphabetically by name (case-insensitive).
 *   - Agents without a `projectId` land in an "Unassigned" group that
 *     always appears last.
 *   - Within each group, original input order is preserved (the API already
 *     returns rows sorted by `startedAt` desc).
 *
 * If an agent's `projectId` doesn't resolve to a known project (stale row,
 * racing delete) we still surface it under a synthesized "Unknown project"
 * label rather than dropping the row silently.
 */
export interface ProjectLike {
	id: string;
	name: string;
}

export interface ActiveAgentRowLike {
	runId: string;
	projectId: string | null;
	// Other fields are passed through untouched, so keep the generic shape open.
	[key: string]: unknown;
}

export interface ActiveAgentsGroup<Row extends ActiveAgentRowLike = ActiveAgentRowLike> {
	projectId: string | null;
	projectName: string;
	agents: Row[];
}

const UNASSIGNED_LABEL = "Unassigned";
const UNKNOWN_LABEL = "Unknown project";

export function groupAgentsByProject<Row extends ActiveAgentRowLike>(
	agents: readonly Row[],
	projects: readonly ProjectLike[],
): ActiveAgentsGroup<Row>[] {
	const projectsById = new Map(projects.map((p) => [p.id, p]));
	const groups = new Map<string, ActiveAgentsGroup<Row>>();

	for (const agent of agents) {
		const key = agent.projectId ?? "__unassigned__";
		let group = groups.get(key);
		if (!group) {
			let projectName: string;
			if (agent.projectId == null) {
				projectName = UNASSIGNED_LABEL;
			} else {
				projectName = projectsById.get(agent.projectId)?.name ?? UNKNOWN_LABEL;
			}
			group = { projectId: agent.projectId, projectName, agents: [] };
			groups.set(key, group);
		}
		group.agents.push(agent);
	}

	return [...groups.values()].sort((a, b) => {
		// Unassigned always last.
		if (a.projectId == null && b.projectId == null) return 0;
		if (a.projectId == null) return 1;
		if (b.projectId == null) return -1;
		return a.projectName.localeCompare(b.projectName, undefined, { sensitivity: "base" });
	});
}
<script lang="ts">
	import { onMount, onDestroy } from "svelte";
	import { buildActiveAgentHref } from "$lib/active-agents-href.js";
	import {
		groupAgentsByProject,
		type ProjectLike,
		type ActiveAgentsGroup,
	} from "$lib/group-active-agents.js";

	type ActiveAgent = {
		runId: string;
		agentName: string;
		conversationId: string;
		parentConversationId: string | null;
		projectId: string | null;
		conversationTitle: string | null;
		startedAt: number;
	};

	let {
		projectId,
		pollMs = 5000,
		groupByProject = false,
	}: { projectId?: string; pollMs?: number; groupByProject?: boolean } = $props();

	let rows = $state<ActiveAgent[]>([]);
	let projects = $state<ProjectLike[]>([]);
	let loading = $state(true);
	let error = $state<string | null>(null);
	let timer: ReturnType<typeof setInterval> | undefined;

	let groups = $derived<ActiveAgentsGroup<ActiveAgent>[]>(
		groupByProject ? groupAgentsByProject(rows, projects) : [],
	);

	async function loadAgents() {
		const qs = projectId ? `?projectId=${encodeURIComponent(projectId)}` : "";
		const res = await fetch(`/api/active-agents${qs}`);
		if (!res.ok) throw new Error(`HTTP ${res.status}`);
		rows = (await res.json()) as ActiveAgent[];
	}

	async function loadProjects() {
		if (!groupByProject) return;
		const res = await fetch(`/api/projects`);
		if (!res.ok) throw new Error(`HTTP ${res.status}`);
		projects = (await res.json()) as ProjectLike[];
	}

	async function load() {
		try {
			await Promise.all([loadAgents(), loadProjects()]);
			error = null;
		} catch (e) {
			error = e instanceof Error ? e.message : String(e);
		} finally {
			loading = false;
		}
	}

	function formatElapsed(startedAt: number): string {
		const seconds = Math.max(0, Math.round((Date.now() - startedAt) / 1000));
		if (seconds < 60) return `${seconds}s`;
		const minutes = Math.floor(seconds / 60);
		const remaining = seconds % 60;
		return `${minutes}m ${remaining}s`;
	}

	onMount(() => {
		load();
		timer = setInterval(load, pollMs);
	});

	onDestroy(() => {
		if (timer) clearInterval(timer);
	});
</script>

{#snippet row(r: ActiveAgent)}
	{@const href = buildActiveAgentHref(r)}
	<a
		{href}
		class="flex items-center justify-between rounded-lg border border-[var(--color-border)] bg-[var(--color-surface-secondary)] px-4 py-3 transition-colors hover:border-[var(--color-accent)]"
	>
		<div class="flex min-w-0 items-center gap-3">
			<span class="relative flex h-2.5 w-2.5 shrink-0">
				<span
					class="absolute inline-flex h-full w-full animate-ping rounded-full bg-green-400 opacity-75"
				></span>
				<span class="relative inline-flex h-2.5 w-2.5 rounded-full bg-green-500"></span>
			</span>
			<span class="truncate text-sm font-medium text-[var(--color-text-primary)]">
				{r.agentName}
			</span>
			{#if r.conversationTitle}
				<span class="truncate text-xs text-[var(--color-text-secondary)]">
					— {r.conversationTitle}
				</span>
			{/if}
		</div>
		<div class="flex shrink-0 items-center gap-3 text-xs text-[var(--color-text-secondary)]">
			<span>{formatElapsed(r.startedAt)}</span>
			<span class="text-[var(--color-text-muted)]">{r.runId.slice(0, 8)}</span>
		</div>
	</a>
{/snippet}

{#if loading && rows.length === 0}
	<p class="text-sm text-[var(--color-text-muted)]">Loading…</p>
{:else if error}
	<p class="text-sm text-red-500">Failed to load: {error}</p>
{:else if rows.length === 0}
	<p class="text-sm text-[var(--color-text-muted)]">No active agents right now.</p>
{:else if groupByProject}
	<div class="flex flex-col gap-6" data-testid="active-agents-grouped">
		{#each groups as group (group.projectId ?? "__unassigned__")}
			<section data-testid="active-agents-group" data-project-id={group.projectId ?? ""}>
				<h3
					class="mb-2 text-sm font-semibold uppercase tracking-wide text-[var(--color-text-secondary)]"
					data-testid="active-agents-group-heading"
				>
					{group.projectName}
					<span class="ml-2 text-xs font-normal normal-case text-[var(--color-text-muted)]">
						({group.agents.length})
					</span>
				</h3>
				<div class="flex flex-col gap-2">
					{#each group.agents as r (r.runId)}
						{@render row(r)}
					{/each}
				</div>
			</section>
		{/each}
	</div>
{:else}
	<div class="flex flex-col gap-2">
		{#each rows as r (r.runId)}
			{@render row(r)}
		{/each}
	</div>
{/if}
<script lang="ts">
	import ActiveAgentsList from "$lib/components/ActiveAgentsList.svelte";
</script>

<div class="space-y-4">
	<div>
		<h1 class="text-2xl font-semibold text-[var(--color-text-primary)]">Active Agents</h1>
		<p class="text-sm text-[var(--color-text-muted)]">
			Chats with a live agent run. Click a row to jump into the conversation.
		</p>
	</div>
	<ActiveAgentsList groupByProject />
</div>
